package mc.bastion.clans;

import org.bukkit.*;
import org.bukkit.command.*;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.event.entity.PlayerDeathEvent;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.event.player.*;
import org.bukkit.inventory.*;
import org.bukkit.inventory.meta.*;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;
import org.bukkit.ChatColor;
import java.io.*;
import java.util.*;
import java.util.regex.*;
import java.util.stream.*;

/** BASTION MC — beta funcional. Almacenamiento YAML y API de consulta para nametags. */
public final class BastionMCClans extends JavaPlugin implements Listener, CommandExecutor, TabCompleter {
    private final Map<String, Clan> clans = new LinkedHashMap<>();
    private final Map<UUID, String> memberships = new HashMap<>();
    private final Map<UUID, String> invitations = new HashMap<>();
    private final Map<UUID, String> requests = new HashMap<>();
    private final Map<UUID, PendingTeleport> teleports = new HashMap<>();
    private final Map<String, Long> killCooldown = new HashMap<>();
    private final Map<UUID, String> chatModes = new HashMap<>();
    private final Map<UUID, Runnable> confirmations = new HashMap<>();
    private YamlConfiguration messages, menus, levels, ranks;
    private File database;
    private static final String[] COLORS = {"negro","azul_oscuro","verde_oscuro","aqua_oscuro","rojo_oscuro","morado_oscuro","dorado","gris","gris_oscuro","azul","verde","aqua","rojo","morado","amarillo","blanco"};
    private static final char[] COLOR_CODES = "0123456789abcdef".toCharArray();
    private static final long DAY = 86400000L;

    @Override public void onEnable() {
        saveDefaultConfig(); for(String f: List.of("messages.yml","menus.yml","levels.yml","ranks.yml")) saveResource(f,false);
        reloadFiles(); database = new File(getDataFolder(),"clans-data.yml"); loadData();
        Objects.requireNonNull(getCommand("clan")).setExecutor(this); Objects.requireNonNull(getCommand("clan")).setTabCompleter(this);
        Objects.requireNonNull(getCommand("bastionclans")).setExecutor(this);
        Bukkit.getPluginManager().registerEvents(this,this);
        Bukkit.getScheduler().runTaskTimer(this, () -> { refreshLevels(); saveData(); }, 1200L, 1200L);
        getLogger().info("BastionMCClans beta activado para Purpur 1.21.11");
    }
    @Override public void onDisable(){ for(PendingTeleport p: teleports.values()) p.task.cancel(); saveData(); }
    private void reloadFiles(){ reloadConfig(); messages=load("messages.yml"); menus=load("menus.yml"); levels=load("levels.yml"); ranks=load("ranks.yml"); }
    private YamlConfiguration load(String file){return YamlConfiguration.loadConfiguration(new File(getDataFolder(),file));}
    public static String color(String s){
        if(s==null)return "";
        Matcher m=Pattern.compile("&#([0-9a-fA-F]{6})").matcher(s); StringBuffer out=new StringBuffer();
        while(m.find()){String hex=m.group(1);StringBuilder b=new StringBuilder("§x");for(char c:hex.toCharArray())b.append('§').append(c);m.appendReplacement(out,Matcher.quoteReplacement(b.toString()));}
        m.appendTail(out);return ChatColor.translateAlternateColorCodes('&',out.toString());
    }
    private String tr(String key){return color(messages.getString(key,key));}
    private void tell(CommandSender to,String key,String... replacements){String s=tr("prefix")+tr(key);for(int i=0;i+1<replacements.length;i+=2)s=s.replace("%"+replacements[i]+"%",replacements[i+1]);to.sendMessage(s);}
    private Clan clan(Player p){String id=memberships.get(p.getUniqueId());return id==null?null:clans.get(id);}
    private Clan find(String name){return clans.get(name.toLowerCase(Locale.ROOT));}
    private boolean officer(Clan c,UUID u){return c!=null && c.rank(u)>=2;}
    private boolean leader(Clan c,UUID u){return c!=null && c.rank(u)==3;}
    private boolean requireClan(Player p,Clan c){if(c==null){tell(p,"no-clan");return false;}return true;}
    private boolean requireOfficer(Player p,Clan c){if(!requireClan(p,c))return false;if(!officer(c,p.getUniqueId())){tell(p,"no-permission");return false;}return true;}
    private boolean requireLeader(Player p,Clan c){if(!requireClan(p,c))return false;if(!leader(c,p.getUniqueId())){tell(p,"no-permission");return false;}return true;}
    private int days(Clan c){return (int)Math.max(0,(System.currentTimeMillis()-c.created)/DAY);}
    private int level(Clan c){int d=days(c);return d>=30||c.kills>=30?3:d>=7||c.kills>=10?2:1;}
    private int limit(int lv,String key){return levels.getInt("levels."+lv+"."+key, lv==1?1:lv==2?2:3);}
    private int score(Clan c){return c.kills*getConfig().getInt("ranking.kill-point",1)-c.deaths*getConfig().getInt("ranking.death-penalty",1)+days(c)*getConfig().getInt("ranking.daily-point",1);}
    private void refreshLevels(){for(Clan c:clans.values()){int lv=level(c);if(lv>c.announcedLevel){c.announcedLevel=lv;broadcast(c,"&a¡Tu clan alcanzó el nivel &e"+lv+"&a!");}}}
    private void broadcast(Clan c,String s){for(UUID u:c.members.keySet()){Player p=Bukkit.getPlayer(u);if(p!=null)p.sendMessage(tr("prefix")+color(s));}}
    private String display(Clan c){return "§"+c.color+c.name;}
    /** API para BastionMCNameTangs: devuelve el nombre coloreado o el símbolo por defecto. */
    public String getClanPlaceholder(UUID player){String id=memberships.get(player);Clan c=id==null?null:clans.get(id);return c==null?color(getConfig().getString("nametag.fallback","&c✘")):display(c);}
    public String getClanName(UUID player){String id=memberships.get(player);Clan c=id==null?null:clans.get(id);return c==null?"":c.name;}

    @Override public boolean onCommand(CommandSender sender,Command cmd,String label,String[] a){
        if(cmd.getName().equalsIgnoreCase("bastionclans")){if(!sender.hasPermission("bastionclans.admin.reload")){tell(sender,"no-permission");return true;}if(a.length>0&&a[0].equalsIgnoreCase("reload")){reloadFiles();tell(sender,"reload");}else sender.sendMessage("/bastionclans reload");return true;}
        if(!(sender instanceof Player p)){sender.sendMessage("Comando solo para jugadores.");return true;}
        Clan c=clan(p);if(a.length==0){openMain(p);return true;}
        String op=a[0].toLowerCase(Locale.ROOT);UUID me=p.getUniqueId();
        switch(op){
            case "ayuda","help" -> p.sendMessage(color("&d/clan crear <nombre>, solicitar <clan>, solicitudes, invitar <jugador>, aceptar <clan>, leave, miembros, info, ranking, explorar, base, setbase, delbase, colorname, pvp, chat, alianza, rival, lider, promover, degradar, expulsar, confirmar, cancelar"));
            case "crear","create" -> {if(c!=null){p.sendMessage(color("&cYa tienes clan."));break;}if(a.length<2){p.sendMessage("/clan crear <nombre>");break;}String name=a[1];int min=getConfig().getInt("clan-name.min-length",3),max=getConfig().getInt("clan-name.max-length",16);if(name.length()<min||name.length()>max||!name.matches(getConfig().getString("clan-name.allowed-pattern","[A-Za-z0-9_]+"))){tell(p,"invalid-name");break;}if(find(name)!=null){tell(p,"clan-exists");break;}Clan n=new Clan(name);n.members.put(me,new Member(3));clans.put(name.toLowerCase(Locale.ROOT),n);memberships.put(me,name.toLowerCase(Locale.ROOT));saveData();tell(p,"clan-created","clan",name);}
            case "info" -> {if(requireClan(p,c))p.sendMessage(color("&d"+c.name+" &7| Nivel &f"+level(c)+" &7| Puntos &f"+score(c)+" &7| Miembros &f"+c.members.size()+" &7| Kills &f"+c.kills+" &7| Muertes &f"+c.deaths+" &7| Días &f"+days(c)));}
            case "explorar","ranking" -> {List<Clan> list=new ArrayList<>(clans.values());list.sort(Comparator.comparingInt(this::score).reversed());p.sendMessage(color("&d&lRanking de clanes"));for(int i=0;i<Math.min(15,list.size());i++){Clan n=list.get(i);p.sendMessage(color("&7"+(i+1)+". ")+display(n)+color(" &8- &f"+score(n)+" puntos &7(Nv."+level(n)+")"));}}
            case "miembros" -> {if(requireClan(p,c))openMembers(p,c);}
            case "solicitar" -> {if(c!=null){p.sendMessage(color("&cYa tienes clan."));break;}if(a.length<2){p.sendMessage("/clan solicitar <clan>");break;}Clan target=find(a[1]);if(target==null){tell(p,"not-found");break;}requests.put(me,target.name.toLowerCase(Locale.ROOT));tell(p,"request-sent","clan",target.name);broadcastOfficers(target,"request-received","player",p.getName(),"clan",target.name);saveData();}
            case "solicitudes" -> {if(!requireOfficer(p,c))break;boolean any=false;for(var e:requests.entrySet())if(e.getValue().equals(c.name.toLowerCase(Locale.ROOT))){any=true;p.sendMessage(color("&e"+playerName(e.getKey())+" &7→ /clan aprobar "+playerName(e.getKey())+" &8| &c/clan rechazar "+playerName(e.getKey())));}if(!any)p.sendMessage(color("&7No hay solicitudes."));}
            case "aprobar","rechazar" -> {if(!requireOfficer(p,c))break;if(a.length<2){p.sendMessage("/clan "+op+" <jugador>");break;}UUID target=knownPlayer(a[1]);if(target==null||!Objects.equals(requests.get(target),c.name.toLowerCase(Locale.ROOT))){tell(p,"not-found");break;}if(op.equals("aprobar")){if(!join(target,c,p))break;tell(p,"request-accepted");}else tell(p,"request-rejected");requests.remove(target);saveData();}
            case "invitar" -> {if(!requireOfficer(p,c))break;if(a.length<2){p.sendMessage("/clan invitar <jugador>");break;}UUID target=knownPlayer(a[1]);if(target==null||memberships.containsKey(target)){tell(p,"not-found");break;}invitations.put(target,c.name.toLowerCase(Locale.ROOT));tell(p,"invite-sent","player",a[1]);Player online=Bukkit.getPlayer(target);if(online!=null)tell(online,"invite-received","clan",c.name);saveData();}
            case "aceptar" -> {if(c!=null){p.sendMessage(color("&cYa tienes clan."));break;}String id=invitations.get(me);if(id==null||(a.length>1&&!id.equalsIgnoreCase(a[1]))){tell(p,"not-found");break;}Clan target=clans.get(id);if(target==null){invitations.remove(me);tell(p,"not-found");break;}if(join(me,target,p)){invitations.remove(me);saveData();}}
            case "leave","salir" -> {if(!requireClan(p,c))break;if(leader(c,me)){UUID successor=c.members.entrySet().stream().filter(e->e.getValue().rank==2).min(Comparator.comparingLong(e->e.getValue().promoted)).map(Map.Entry::getKey).orElse(null);if(successor==null){confirm(p,"&c¿Eliminar el clan y todo su progreso?",()->{deleteClan(c);tell(p,"clan-disbanded");});break;}c.members.get(successor).rank=3;broadcast(c,"&e"+playerName(successor)+" ahora es líder.");}c.members.remove(me);memberships.remove(me);saveData();tell(p,"clan-left");}
            case "colorname" -> {if(!requireOfficer(p,c))break;if(a.length<2){p.sendMessage(color("&eColores: &f"+String.join(", ",COLORS)));break;}int index=Arrays.asList(COLORS).indexOf(a[1].toLowerCase(Locale.ROOT));if(index<0){p.sendMessage(color("&cColor inválido. &f"+String.join(", ",COLORS)));break;}c.color=COLOR_CODES[index];saveData();tell(p,"color-changed");}
            case "setbase","delbase","base" -> {if(!requireClan(p,c))break;int number=1;if(a.length>1){try{number=Integer.parseInt(a[1]);}catch(NumberFormatException ex){p.sendMessage(color("&cUsa un número de base."));break;}}if(number<1||number>limit(level(c),"bases")){p.sendMessage(color("&cTu nivel no permite esa base."));break;}if(op.equals("setbase")){if(!requireOfficer(p,c))break;c.bases.put(number,p.getLocation().clone());tell(p,"base-set","number",""+number);saveData();}else if(op.equals("delbase")){if(!requireOfficer(p,c))break;c.bases.remove(number);tell(p,"base-removed","number",""+number);saveData();}else{Location destination=c.bases.get(number);if(destination==null){tell(p,"base-missing");break;}beginTeleport(p,destination);}}
            case "pvp" -> {if(!requireLeader(p,c))break;confirm(p,"&c¿Cambiar el PvP interno? Puede causar pérdida de objetos.",()->{c.pvp=!c.pvp;saveData();broadcast(c,tr(c.pvp?"pvp-enabled":"pvp-disabled"));});}
            case "chat" -> {if(!requireClan(p,c))break;String mode=a.length>1&&a[1].equalsIgnoreCase("alianza")?"alliance":"clan";if(mode.equals("alliance")&&c.allies.isEmpty()){p.sendMessage(color("&cNo tienes alianzas."));break;}if(mode.equals(chatModes.get(me))){chatModes.remove(me);p.sendMessage(color("&aChat público activado."));}else{chatModes.put(me,mode);p.sendMessage(color("&aChat "+(mode.equals("clan")?"del clan":"de alianza")+" activado."));}}
            case "alianza" -> {if(!requireClan(p,c))break;if(a.length==1){p.sendMessage(color("&aAlianzas: &f"+String.join(", ",c.allies)));break;}if(!requireOfficer(p,c))break;relationship(p,c,a,true);}
            case "rival" -> {if(!requireClan(p,c))break;if(a.length==1){p.sendMessage(color("&cRivales: &f"+String.join(", ",c.rivals)));break;}if(!requireOfficer(p,c))break;relationship(p,c,a,false);}
            case "promover","degradar","expulsar" -> {if(!requireOfficer(p,c))break;if(a.length<2){p.sendMessage("/clan "+op+" <jugador>");break;}UUID target=knownPlayer(a[1]);Member member=target==null?null:c.members.get(target);if(member==null||target.equals(me)||member.rank>=c.rank(me)){tell(p,"no-permission");break;}if(op.equals("expulsar")){confirm(p,"&c¿Expulsar a "+a[1]+"?",()->{c.members.remove(target);memberships.remove(target);saveData();broadcast(c,"&c"+a[1]+" fue expulsado.");});break;}int next=member.rank+(op.equals("promover")?1:-1);if(next<0||next>2||(!leader(c,me)&&next>1)){tell(p,"no-permission");break;}member.rank=next;member.promoted=System.currentTimeMillis();saveData();p.sendMessage(color("&aRango actualizado."));}
            case "lider" -> {if(!requireLeader(p,c))break;if(a.length<3||!a[1].equalsIgnoreCase("transferir")){p.sendMessage("/clan lider transferir <jugador>");break;}UUID target=knownPlayer(a[2]);if(target==null||!c.members.containsKey(target)||target.equals(me)){tell(p,"not-found");break;}confirm(p,"&e¿Transferir el liderazgo a "+a[2]+"?",()->{c.members.get(me).rank=2;c.members.get(me).promoted=System.currentTimeMillis();c.members.get(target).rank=3;saveData();broadcast(c,"&eNuevo líder: "+a[2]);});}
            case "confirmar" -> {Runnable action=confirmations.remove(me);if(action==null)p.sendMessage(color("&cNo hay confirmación pendiente."));else action.run();}
            case "cancelar" -> {confirmations.remove(me);p.sendMessage(color("&eAcción cancelada."));}
            case "admin" -> {if(!p.hasPermission("bastionclans.admin.delete")){tell(p,"no-permission");break;}if(a.length<3||!a[1].equalsIgnoreCase("delete")){p.sendMessage("/clan admin delete <clan>");break;}Clan target=find(a[2]);if(target==null){tell(p,"not-found");break;}confirm(p,"&c¿ELIMINAR permanentemente "+target.name+"?",()->{getLogger().warning("ADMIN DELETE: "+p.getName()+" eliminó "+target.name);deleteClan(target);tell(p,"clan-disbanded");});}
            default -> tell(p,"usage");
        }
        return true;
    }
    private void confirm(Player p,String warning,Runnable action){confirmations.put(p.getUniqueId(),action);p.sendMessage(tr("prefix")+color(warning));p.sendMessage(color("&a/clan confirmar &8| &c/clan cancelar"));}
    private void broadcastOfficers(Clan c,String key,String... args){for(var e:c.members.entrySet())if(e.getValue().rank>=2){Player online=Bukkit.getPlayer(e.getKey());if(online!=null)tell(online,key,args);}}
    private boolean join(UUID player,Clan c,Player messenger){if(memberships.containsKey(player)){messenger.sendMessage(color("&cEse jugador ya tiene clan."));return false;}if(c.members.size()>=limit(level(c),"members")){tell(messenger,"clan-full");return false;}c.members.put(player,new Member(0));memberships.put(player,c.name.toLowerCase(Locale.ROOT));Player target=Bukkit.getPlayer(player);if(target!=null)tell(target,"clan-joined","clan",c.name);return true;}
    private void deleteClan(Clan c){String id=c.name.toLowerCase(Locale.ROOT);for(UUID u:c.members.keySet()){memberships.remove(u);chatModes.remove(u);}for(Clan other:clans.values()){other.allies.remove(id);other.rivals.remove(id);other.pendingAllies.remove(id);}invitations.values().removeIf(v->v.equals(id));requests.values().removeIf(v->v.equals(id));clans.remove(id);saveData();}
    private void relationship(Player p,Clan c,String[] a,boolean alliance){if(a.length<3){p.sendMessage("/clan "+(alliance?"alianza invitar|aceptar|rechazar|eliminar":"rival agregar|eliminar")+" <clan>");return;}Clan target=find(a[2]);if(target==null||target==c){tell(p,"not-found");return;}String id=c.name.toLowerCase(Locale.ROOT),other=target.name.toLowerCase(Locale.ROOT);String op=a[1].toLowerCase(Locale.ROOT);
        if(alliance){switch(op){case "invitar"->{if(c.allies.size()>=limit(level(c),"alliances")||target.allies.size()>=limit(level(target),"alliances")||c.rivals.contains(other)){p.sendMessage(color("&cNo se puede formar esa alianza."));return;}target.pendingAllies.add(id);tell(p,"alliance-sent","clan",target.name);broadcast(target,"&eSolicitud de alianza de &f"+c.name+" &e(/clan alianza aceptar "+c.name+")");}case "aceptar"->{if(!c.pendingAllies.contains(other)||c.allies.size()>=limit(level(c),"alliances")||target.allies.size()>=limit(level(target),"alliances")){tell(p,"not-found");return;}c.pendingAllies.remove(other);c.allies.add(other);target.allies.add(id);broadcast(c,"&aAlianza con "+target.name);broadcast(target,"&aAlianza con "+c.name);}case "rechazar"->c.pendingAllies.remove(other);case "eliminar"->{c.allies.remove(other);target.allies.remove(id);}default->{p.sendMessage(color("&cSubcomando inválido."));return;}}}
        else {switch(op){case "agregar"->{int max=levels.getInt("rivals-max",5);if(c.rivals.size()>=max||target.rivals.size()>=max){tell(p,"rival-full");return;}if(c.allies.contains(other)){p.sendMessage(color("&cNo puedes declarar rival a un aliado."));return;}c.rivals.add(other);target.rivals.add(id);broadcast(c,"&cRivalidad con "+target.name);broadcast(target,"&c"+c.name+" os ha declarado rivales.");}case "eliminar"->{c.rivals.remove(other);target.rivals.remove(id);}default->{p.sendMessage(color("&cSubcomando inválido."));return;}}}saveData();}
    @SuppressWarnings("deprecation") private UUID knownPlayer(String name){Player p=Bukkit.getPlayerExact(name);if(p!=null)return p.getUniqueId();OfflinePlayer off=Bukkit.getOfflinePlayer(name);return off.hasPlayedBefore()?off.getUniqueId():null;}
    private String playerName(UUID id){OfflinePlayer off=Bukkit.getOfflinePlayer(id);return off.getName()==null?id.toString().substring(0,8):off.getName();}
    private void beginTeleport(Player p,Location dest){PendingTeleport prev=teleports.remove(p.getUniqueId());if(prev!=null)prev.task.cancel();int sec=Math.max(0,getConfig().getInt("teleport.delay-seconds",5));if(sec==0){p.teleport(dest);tell(p,"teleport-done");return;}tell(p,"teleport-start","seconds",""+sec);Location start=p.getLocation().clone();BukkitTask task=Bukkit.getScheduler().runTaskLater(this,()->{teleports.remove(p.getUniqueId());if(p.isOnline()&&p.getWorld().equals(start.getWorld())){p.teleport(dest);tell(p,"teleport-done");}},sec*20L);teleports.put(p.getUniqueId(),new PendingTeleport(start,task));}
    private void cancelTeleport(Player p){PendingTeleport t=teleports.remove(p.getUniqueId());if(t!=null){t.task.cancel();tell(p,"teleport-cancel");}}
    @EventHandler public void move(PlayerMoveEvent e){PendingTeleport t=teleports.get(e.getPlayer().getUniqueId());if(t==null||e.getTo()==null)return;Location to=e.getTo();if(!Objects.equals(t.start.getWorld(),to.getWorld())||getConfig().getBoolean("teleport.cancel-on-movement",true)&&(t.start.getX()!=to.getX()||t.start.getY()!=to.getY()||t.start.getZ()!=to.getZ()))cancelTeleport(e.getPlayer());}
    @EventHandler public void damage(org.bukkit.event.entity.EntityDamageEvent e){if(e.getEntity() instanceof Player p&&getConfig().getBoolean("teleport.cancel-on-damage",true))cancelTeleport(p);}
    @EventHandler public void quit(PlayerQuitEvent e){cancelTeleport(e.getPlayer());chatModes.remove(e.getPlayer().getUniqueId());confirmations.remove(e.getPlayer().getUniqueId());}
    @EventHandler public void join(PlayerJoinEvent e){Player p=e.getPlayer();String inv=invitations.get(p.getUniqueId());if(inv!=null&&clans.containsKey(inv))tell(p,"invite-received","clan",clans.get(inv).name);}
    @EventHandler(ignoreCancelled=true) public void friendlyFire(EntityDamageByEntityEvent e){if(!(e.getEntity() instanceof Player victim))return;Player attacker=null;if(e.getDamager() instanceof Player p)attacker=p;else if(e.getDamager() instanceof org.bukkit.entity.Projectile projectile&&projectile.getShooter() instanceof Player p)attacker=p;if(attacker==null)return;Clan a=clan(attacker),b=clan(victim);if(a==null||b==null)return;if(a==b&&!a.pvp||a!=b&&a.allies.contains(b.name.toLowerCase(Locale.ROOT)))e.setCancelled(true);}
    @EventHandler public void death(PlayerDeathEvent e){Player dead=e.getEntity();Clan c=clan(dead);if(c!=null){c.deaths++;c.members.get(dead.getUniqueId()).deaths++;}Player killer=dead.getKiller();if(killer==null)return;Clan k=clan(killer);if(k==null||k==c)return;String pair=killer.getUniqueId()+":"+dead.getUniqueId();long now=System.currentTimeMillis();long cooldown=getConfig().getLong("pvp.repeated-kill-cooldown-minutes",30)*60000L;if(now-killCooldown.getOrDefault(pair,0L)<cooldown)return;killCooldown.put(pair,now);k.kills++;k.members.get(killer.getUniqueId()).kills++;refreshLevels();saveData();}
    @EventHandler(ignoreCancelled=true) public void chat(AsyncPlayerChatEvent e){String mode=chatModes.get(e.getPlayer().getUniqueId());if(mode==null)return;Clan c=clan(e.getPlayer());if(c==null)return;e.setCancelled(true);String msg=color("&8["+(mode.equals("clan")?"&bClan":"&aAlianza")+"&8] &f"+e.getPlayer().getName()+"&7: &f")+e.getMessage();Set<UUID> recipients=new HashSet<>(c.members.keySet());if(mode.equals("alliance"))for(String id:c.allies){Clan ally=clans.get(id);if(ally!=null)recipients.addAll(ally.members.keySet());}Bukkit.getScheduler().runTask(this,()->{for(UUID u:recipients){Player p=Bukkit.getPlayer(u);if(p!=null)p.sendMessage(msg);}Bukkit.getConsoleSender().sendMessage(ChatColor.stripColor(msg));});}
    private ItemStack item(String path,Material fallback){String name=menus.getString(path+".material",fallback.name());Material mat=Material.matchMaterial(name);if(mat==null)mat=fallback;ItemStack stack=new ItemStack(mat);ItemMeta meta=stack.getItemMeta();if(meta!=null){meta.setDisplayName(color(menus.getString(path+".name",path)));meta.setLore(menus.getStringList(path+".lore").stream().map(BastionMCClans::color).toList());stack.setItemMeta(meta);}return stack;}
    private void openMain(Player p){Inventory inv=Bukkit.createInventory(null,54,color(menus.getString("main.title","&dBASTION | Clanes")));Clan c=clan(p);String path=c==null?"main.no-clan":"main.items";ConfigurationSection sec=menus.getConfigurationSection(path);if(sec!=null)for(String key:sec.getKeys(false)){int slot=menus.getInt(path+"."+key+".slot",0);if(slot>=0&&slot<54)inv.setItem(slot,item(path+"."+key,Material.PAPER));}p.openInventory(inv);}
    private void openMembers(Player p,Clan c){Inventory inv=Bukkit.createInventory(null,54,color("&dMiembros | "+c.name));int i=0;for(var e:c.members.entrySet()){if(i>=54)break;ItemStack skull=new ItemStack(Material.PLAYER_HEAD);SkullMeta meta=(SkullMeta)skull.getItemMeta();meta.setOwningPlayer(Bukkit.getOfflinePlayer(e.getKey()));meta.setDisplayName(color("&e"+playerName(e.getKey())));Member m=e.getValue();meta.setLore(List.of(color("&7Rango: &f"+rankName(m.rank)),color("&7Kills: &f"+m.kills),color("&7Muertes: &f"+m.deaths),color("&7Puntos semanales: &f"+(m.kills-m.deaths)),color("&7Días en clan: &f"+((System.currentTimeMillis()-m.joined)/DAY))));skull.setItemMeta(meta);inv.setItem(i++,skull);}p.openInventory(inv);}
    private String rankName(int rank){return switch(rank){case 3->"Líder";case 2->"Colíder";case 1->"Veterano";default->"Miembro";};}
    @EventHandler public void click(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p))return;String title=e.getView().getTitle();if(title.equals(color(menus.getString("main.title","&dBASTION | Clanes")))){e.setCancelled(true);if(e.getClickedInventory()!=e.getView().getTopInventory())return;ItemStack clicked=e.getCurrentItem();if(clicked==null||!clicked.hasItemMeta())return;String path=clan(p)==null?"main.no-clan":"main.items";ConfigurationSection sec=menus.getConfigurationSection(path);if(sec==null)return;for(String key:sec.getKeys(false))if(menus.getInt(path+"."+key+".slot",-1)==e.getSlot()){p.closeInventory();switch(key){case "info"->onCommand(p,Objects.requireNonNull(getCommand("clan")),"clan",new String[]{"info"});case "members"->onCommand(p,Objects.requireNonNull(getCommand("clan")),"clan",new String[]{"miembros"});case "rankings"->onCommand(p,Objects.requireNonNull(getCommand("clan")),"clan",new String[]{"ranking"});case "explore"->onCommand(p,Objects.requireNonNull(getCommand("clan")),"clan",new String[]{"explorar"});case "requests"->onCommand(p,Objects.requireNonNull(getCommand("clan")),"clan",new String[]{"solicitudes"});case "bases"->p.sendMessage(color("&eUsa /clan base [1-3]"));case "alliances"->p.sendMessage(color("&eUsa /clan alianza"));case "rivals"->p.sendMessage(color("&eUsa /clan rival"));case "levels"->onCommand(p,Objects.requireNonNull(getCommand("clan")),"clan",new String[]{"info"});case "create"->p.sendMessage(color("&eUsa /clan crear <nombre>"));case "leave"->onCommand(p,Objects.requireNonNull(getCommand("clan")),"clan",new String[]{"leave"});}return;}}
        else if(title.startsWith(color("&dMiembros | ")))e.setCancelled(true);
    }
    @Override public List<String> onTabComplete(CommandSender sender,Command cmd,String alias,String[] a){if(!(sender instanceof Player p)||a.length==0)return List.of();Clan c=clan(p);List<String> choices=new ArrayList<>();if(a.length==1){choices.addAll(List.of("ayuda","info","explorar","ranking","miembros","solicitudes","crear","solicitar","invitar","aceptar","aprobar","rechazar","leave","base","setbase","delbase","colorname","chat","alianza","rival","promover","degradar","expulsar","lider","confirmar","cancelar"));if(leader(c,p.getUniqueId()))choices.add("pvp");if(p.hasPermission("bastionclans.admin.delete"))choices.add("admin");}else{String op=a[0].toLowerCase(Locale.ROOT);if(a.length==2){switch(op){case "colorname"->choices.addAll(List.of(COLORS));case "base","setbase","delbase"->choices.addAll(List.of("1","2","3"));case "chat"->choices.add("alianza");case "alianza"->choices.addAll(List.of("invitar","aceptar","rechazar","eliminar"));case "rival"->choices.addAll(List.of("agregar","eliminar"));case "lider"->choices.add("transferir");case "admin"->{if(p.hasPermission("bastionclans.admin.delete"))choices.add("delete");}case "solicitar","aceptar"->choices.addAll(clans.values().stream().map(n->n.name).toList());case "invitar","aprobar","rechazar","promover","degradar","expulsar"->choices.addAll(Bukkit.getOnlinePlayers().stream().map(Player::getName).toList());}}else if(a.length==3&&List.of("alianza","rival","admin").contains(op))choices.addAll(clans.values().stream().map(n->n.name).toList());else if(a.length==3&&op.equals("lider"))choices.addAll(c==null?List.of():c.members.keySet().stream().map(this::playerName).toList());}String prefix=a[a.length-1].toLowerCase(Locale.ROOT);return choices.stream().filter(s->s.toLowerCase(Locale.ROOT).startsWith(prefix)).distinct().sorted().toList();}
    private void loadData(){if(!database.exists())return;YamlConfiguration y=YamlConfiguration.loadConfiguration(database);ConfigurationSection root=y.getConfigurationSection("clans");if(root!=null)for(String id:root.getKeys(false)){String path="clans."+id+".";Clan c=new Clan(y.getString(path+"name",id));c.created=y.getLong(path+"created",System.currentTimeMillis());String cc=y.getString(path+"color","f");c.color=cc.isEmpty()?'f':cc.charAt(0);c.pvp=y.getBoolean(path+"pvp");c.kills=y.getInt(path+"kills");c.deaths=y.getInt(path+"deaths");c.announcedLevel=y.getInt(path+"announced-level",1);c.allies.addAll(y.getStringList(path+"allies"));c.rivals.addAll(y.getStringList(path+"rivals"));c.pendingAllies.addAll(y.getStringList(path+"pending-allies"));ConfigurationSection mem=y.getConfigurationSection(path+"members");if(mem!=null)for(String u:mem.getKeys(false))try{UUID uuid=UUID.fromString(u);Member m=new Member(y.getInt(path+"members."+u+".rank"));m.joined=y.getLong(path+"members."+u+".joined",c.created);m.promoted=y.getLong(path+"members."+u+".promoted",m.joined);m.kills=y.getInt(path+"members."+u+".kills");m.deaths=y.getInt(path+"members."+u+".deaths");c.members.put(uuid,m);memberships.put(uuid,id);}catch(IllegalArgumentException ignored){}for(int i=1;i<=3;i++){String raw=y.getString(path+"bases."+i);if(raw!=null){String[] bits=raw.split(";");try{World w=Bukkit.getWorld(bits[0]);if(w!=null)c.bases.put(i,new Location(w,Double.parseDouble(bits[1]),Double.parseDouble(bits[2]),Double.parseDouble(bits[3]),Float.parseFloat(bits[4]),Float.parseFloat(bits[5])));}catch(Exception ignored){}}}clans.put(id,c);}readUUIDMap(y,"invitations",invitations);readUUIDMap(y,"requests",requests);}
    private void readUUIDMap(YamlConfiguration y,String key,Map<UUID,String> into){ConfigurationSection s=y.getConfigurationSection(key);if(s!=null)for(String id:s.getKeys(false))try{into.put(UUID.fromString(id),s.getString(id,""));}catch(IllegalArgumentException ignored){}}
    private void saveData(){if(database==null)return;YamlConfiguration y=new YamlConfiguration();for(var e:clans.entrySet()){String path="clans."+e.getKey()+".";Clan c=e.getValue();y.set(path+"name",c.name);y.set(path+"created",c.created);y.set(path+"color",String.valueOf(c.color));y.set(path+"pvp",c.pvp);y.set(path+"kills",c.kills);y.set(path+"deaths",c.deaths);y.set(path+"announced-level",c.announcedLevel);y.set(path+"allies",new ArrayList<>(c.allies));y.set(path+"rivals",new ArrayList<>(c.rivals));y.set(path+"pending-allies",new ArrayList<>(c.pendingAllies));for(var member:c.members.entrySet()){String base=path+"members."+member.getKey()+".";Member m=member.getValue();y.set(base+"rank",m.rank);y.set(base+"joined",m.joined);y.set(base+"promoted",m.promoted);y.set(base+"kills",m.kills);y.set(base+"deaths",m.deaths);}for(var b:c.bases.entrySet()){Location l=b.getValue();y.set(path+"bases."+b.getKey(),l.getWorld().getName()+";"+l.getX()+";"+l.getY()+";"+l.getZ()+";"+l.getYaw()+";"+l.getPitch());}}for(var e:invitations.entrySet())y.set("invitations."+e.getKey(),e.getValue());for(var e:requests.entrySet())y.set("requests."+e.getKey(),e.getValue());try{y.save(database);}catch(IOException ex){getLogger().severe("No se pudo guardar clans-data.yml: "+ex.getMessage());}}
    private static final class Clan {final String name;long created=System.currentTimeMillis();char color='f';boolean pvp;int kills,deaths,announcedLevel=1;final Map<UUID,Member> members=new LinkedHashMap<>();final Map<Integer,Location> bases=new HashMap<>();final Set<String> allies=new HashSet<>(),rivals=new HashSet<>(),pendingAllies=new HashSet<>();Clan(String name){this.name=name;}int rank(UUID id){Member m=members.get(id);return m==null?-1:m.rank;}}
    private static final class Member {int rank,kills,deaths;long joined=System.currentTimeMillis(),promoted=joined;Member(int rank){this.rank=rank;}}
    private record PendingTeleport(Location start,BukkitTask task){}
}
